cat > /tmp/dose.py <<'PY'
import workcell

def call(a,b):
 r=workcell.call(a,b)
 print(r.text,flush=True)
 if not r.ok: raise RuntimeError(r.text)
 return r

def mass(): return workcell.call('scale','read').data['gross_g']

def finish(jar,tare):
 target=tare+250
 for n in range(100):
  current=mass(); diff=round(target-current,2)
  print(jar,'gross',current,'diff',diff,flush=True)
  if abs(diff)<=0.14:
   call('checkweigher','check'); return
  if diff < -0.14: call('robot','remove')
  elif diff > 1.0: call('robot','dose fine')
  else: call('robot','dose micro')
 raise RuntimeError('too many doses')
finish('J1',121.23)
PY
python3 /tmp/dose.py; station status

